# Given table contents
years = [1982, 1983, 1984, 1985, 1986, 1987, 1988, 1989, 1990, 1991, 1992, 1993, 1994, 1995, 1996, 1997, 1998, 1999]
titles = ["sleeping beauty and other favourite fairy tales", "gorilla", "granpa", "the iron man", "the jolly postman", "jack the treacle eater", "alice's adventures in wonderland", "the park in the dark", "all join in", "have you seen who's just moved in next door to us?", "the man", "think of an eel", "so much", "the little boat", "drop dead", "lady muck", "voices in the park", "alice's adventures in wonderland"]

# Subquestion 1: Count the occurrences of each book title in the 'titles' list.
book_counts = {}
for title in titles:
  if title in book_counts:
    book_counts[title] += 1
  else:
    book_counts[title] = 1

# Subquestion 2: Find the titles that have a count of 2.
books_with_two_awards = []
for title, count in book_counts.items():
  if count == 2:
    books_with_two_awards.append(title)

# Print the final answer
print(f"Final Answer: {books_with_two_awards}")
# Done
